O1=np.array(G['Demo pair 1 output']); O2=np.array(G['Demo pair 2 output'])
def rule(a,b):  # a vertical, b horizontal, from seed
    return (a%2==0 and b<=a) or (b%2==0 and b>a)
def solve(inp):
    inp=np.array(inp); h,w=inp.shape
    bg=int(np.bincount(inp.flatten()).argmax())
    seeds=[(r,c,int(inp[r,c])) for r in range(h) for c in range(w) if inp[r,c]!=bg]
    out=[[bg]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            best=min(seeds,key=lambda s:(abs(r-s[0])+abs(c-s[1]),s[0],s[1]))
            a,b=abs(r-best[0]),abs(c-best[1])
            if rule(a,b): out[r][c]=best[2]
    return out
